import type { MetadataRoute } from "next";
import { SCHOOL_NAME } from "@/lib/school";

/**
 * Installable-web-app manifest, served at `/manifest.webmanifest`.
 *
 * Icons are the school's square mark at three sizes: a normal 192/512 pair and
 * a `maskable` 512 for launchers that crop to their own shape (Android's
 * circle/squircle). The artwork sits inside the maskable safe zone, so the
 * arch never loses its point. Generated by `npm run brand:images`.
 *
 * Next renders this file at build time; the school name is the build-time
 * fallback, which is what an installed icon should be labelled with anyway.
 *
 * `force-static` is required by the Capacitor target (`output: "export"`), which
 * cannot pre-render a dynamic route; the web target is unaffected.
 */
export const dynamic = "force-static";
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: SCHOOL_NAME,
    short_name: SCHOOL_NAME.split(" ")[0] ?? SCHOOL_NAME,
    description:
      "A single-school learning platform for students, parents and teachers.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#0E2B52",
    theme_color: "#0E2B52",
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png" },
      {
        src: "/icons/maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
